namespace Exiled.CustomRoles.Commands
{
    using System;
    using System.Collections.Generic;
    using System.Collections.ObjectModel;
    using System.Linq;
    using System.Text;

    using CommandSystem;
    using Exiled.API.Extensions;
    using Exiled.API.Features;
    using Exiled.API.Features.Pools;
    using Exiled.CustomRoles.API;
    using Exiled.CustomRoles.API.Features;
    using Exiled.Permissions.Extensions;
    using HarmonyLib;

    /// <summary>
    /// The command to get specified player(s) current custom roles.
    /// </summary>
    internal sealed class Get : ICommand
    {
        private Get()
        {
        }

        /// <summary>
        /// Gets the <see cref="Get"/> command instance.
        /// </summary>
        public static Get Instance { get; } = new();

        /// <inheritdoc/>
        public string Command => "get";

        /// <inheritdoc/>
        public string[] Aliases { get; } = Array.Empty<string>();

        /// <inheritdoc/>
        public string Description => "Gets the specified player(s)' current custom role(s).";

        /// <inheritdoc/>
        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            if (!sender.CheckPermission("customroles.get"))
            {
                response = "Permission Denied, required: customroles.get";
                return false;
            }

            List<Player> players = ListPool<Player>.Pool.Get();

            if (arguments.Count > 0)
            {
                string identifier = string.Join(" ", arguments);

                switch (identifier.ToLower())
                {
                    case "*":
                    case "all":
                        players.AddRange(Player.List);
                        break;
                    default:
                        players.AddRange(Player.GetProcessedData(arguments));
                        break;
                }

                if (players.IsEmpty())
                {
                    if (arguments.Count > 0 || !Player.TryGet(sender, out Player player))
                    {
                        response = $"Player not found: {identifier}";
                        return false;
                    }

                    players.Add(player);
                }
            }
            else
            {
                response = "get <Nickname/PlayerID/UserID/all/*>";
                return false;
            }

            StringBuilder builder = StringBuilderPool.Pool.Get();

            builder.AppendLine();
            builder.AppendLine("====================== Custom Roles ======================");

            foreach (Player target in players)
            {
                ReadOnlyCollection<CustomRole> roles = target.GetCustomRoles();
                builder.Append((target.DisplayNickname + (target.HasCustomName ? $" ({target.Nickname})" : string.Empty)).PadRight(30 + (target.HasCustomName ? 23 : 0)));
                builder.Append(" ");
                builder.Append($"({target.Id})".PadRight(5));
                if (roles.IsEmpty())
                {
                    builder.AppendLine(" | No Custom Role");
                }
                else
                {
                    // builder.Append($" | [{string.Join(", ", roles.Select(role => $"<color={role.Role.GetColor().ToHex()}>{role}</color>"))}]");
                    builder.Append(" | [");
                    builder.Append(string.Join(", ", roles.Select(role => $"<color={role.Role.GetColor().ToHex()}>{role}</color>")));
                    builder.AppendLine("]");
                }
            }

            builder.AppendLine("==========================================================");

            ListPool<Player>.Pool.Return(players);

            response = StringBuilderPool.Pool.ToStringReturn(builder);
            return true;
        }
    }
}

namespace Exiled.CustomRoles.Commands
{
    using System;
    using System.Collections.Generic;
    using System.Linq;

    using CommandSystem;

    using Exiled.API.Features;
    using Exiled.API.Features.Pools;
    using Exiled.CustomRoles.API.Features;
    using Exiled.Permissions.Extensions;

    using RemoteAdmin;

    /// <summary>
    /// The command to give a role to player(s).
    /// </summary>
    internal sealed class Give : ICommand
    {
        private Give()
        {
        }

        /// <summary>
        /// Gets the <see cref="Give"/> command instance.
        /// </summary>
        public static Give Instance { get; } = new();

        /// <inheritdoc/>
        public string Command { get; } = "give";

        /// <inheritdoc/>
        public string[] Aliases { get; } = { "g" };

        /// <inheritdoc/>
        public string Description { get; } = "Gives the specified custom role to the indicated player(s).";

        /// <inheritdoc/>
        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            try
            {
                if (!sender.CheckPermission("customroles.give"))
                {
                    response = "Permission Denied, required: customroles.give";
                    return false;
                }

                if (arguments.Count == 0)
                {
                    response = "give <Custom role name/Custom role ID> [Nickname/PlayerID/UserID/all/*]";
                    return false;
                }

                if (!CustomRole.TryGet(arguments.At(0), out CustomRole? role) || role is null)
                {
                    response = $"Custom role {arguments.At(0)} not found!";
                    return false;
                }

                if (arguments.Count == 1)
                {
                    if (sender is PlayerCommandSender playerCommandSender)
                    {
                        Player player = Player.Get(playerCommandSender);

                        role.AddRole(player);
                        response = $"{role.Name} given to {player.Nickname}.";
                        return true;
                    }

                    response = "Failed to provide a valid player.";
                    return false;
                }

                string identifier = string.Join(" ", arguments.Skip(1));

                switch (identifier.ToLower())
                {
                    case "*":
                    case "all":
                        List<Player> players = ListPool<Player>.Pool.Get(Player.List);

                        foreach (Player player in players)
                            role.AddRole(player);

                        response = $"Custom role {role.Name} given to all players.";
                        ListPool<Player>.Pool.Return(players);
                        return true;
                    default:
                        break;
                }

                IEnumerable<Player> list = Player.GetProcessedData(arguments, 1);
                if (list.IsEmpty())
                {
                    response = "Cannot find player! Try using the player ID!";
                    return false;
                }

                foreach (Player player in list)
                    role.AddRole(player);

                response = $"Customrole {role.Name} given to {list.Count()} players!";

                return true;
            }
            catch (Exception e)
            {
                Log.Error(e);
                response = "Error";
                return false;
            }
        }
    }
}

