namespace Exiled.CustomRoles.Commands
{
    using System;
    using System.Linq;

    using CommandSystem;

    using Exiled.API.Features;
    using Exiled.CustomRoles.API;
    using Exiled.CustomRoles.API.Features;

    /// <summary>
    /// Handles the using of custom role abilities.
    /// </summary>
    [CommandHandler(typeof(ClientCommandHandler))]
    public class UseAbility : ICommand
    {
        /// <inheritdoc/>
        public string Command { get; } = "useability";

        /// <inheritdoc/>
        public string[] Aliases { get; } = { "special" };

        /// <inheritdoc/>
        public string Description { get; } = "Use your custom roles special ability, if available.";

        /// <inheritdoc/>
        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            Player player = Player.Get((CommandSender)sender);
            string abilityName = string.Empty;
            ActiveAbility? ability;

            if (arguments.Count > 0)
            {
                foreach (string s in arguments.Skip(1))
                    abilityName += s;

                if (!CustomAbility.TryGet(abilityName, out CustomAbility? customAbility) || customAbility is null)
                {
                    response = $"Ability {abilityName} does not exist.";
                    return false;
                }

                if (customAbility is not ActiveAbility activeAbility)
                {
                    response = $"{abilityName} is not an active ability.";
                    return false;
                }

                ability = activeAbility;
            }
            else
            {
                ability = player.GetSelectedAbility();
            }

            if (ability is null)
            {
                response = "No selected ability.";
                return false;
            }

            if (!ability.CanUseAbility(player, out response, CustomRoles.Instance.Config.ActivateOnlySelected))
                return false;
            response = $"{ability.Name} has been used.";
            ability.UseAbility(player);
            return true;
        }
    }
}

namespace Exiled.CustomRoles.Events
{
    using System;
    using System.Collections.Generic;
    using System.Threading;

    using Exiled.API.Enums;
    using Exiled.API.Features;
    using Exiled.CustomRoles.API;
    using Exiled.CustomRoles.API.Features;
    using Exiled.Events.EventArgs.Player;

    using UnityEngine;

    /// <summary>
    /// Handles general events for players.
    /// </summary>
    public class PlayerHandlers
    {
        private static readonly HashSet<SpawnReason> ValidSpawnReasons = new()
        {
            SpawnReason.RoundStart,
            SpawnReason.Respawn,
            SpawnReason.LateJoin,
            SpawnReason.Revived,
            SpawnReason.Escaped,
            SpawnReason.ItemUsage,
        };

        private readonly CustomRoles plugin;

        /// <summary>
        /// Initializes a new instance of the <see cref="PlayerHandlers"/> class.
        /// </summary>
        /// <param name="plugin">The <see cref="CustomRoles"/> plugin instance.</param>
        public PlayerHandlers(CustomRoles plugin)
        {
            this.plugin = plugin;
        }

        /// <inheritdoc cref="Exiled.Events.Handlers.Server.WaitingForPlayers"/>
        internal void OnWaitingForPlayers()
        {
            foreach (CustomRole role in CustomRole.Registered)
            {
                role.SpawnedPlayers = 0;
            }
        }

        /// <inheritdoc cref="Exiled.Events.Handlers.Player.SpawningRagdoll"/>
        internal void OnSpawningRagdoll(SpawningRagdollEventArgs ev)
        {
            if (plugin.StopRagdollPlayers.Contains(ev.Player))
            {
                ev.IsAllowed = false;
                plugin.StopRagdollPlayers.Remove(ev.Player);
            }
        }

        /// <inheritdoc cref="Exiled.Events.Handlers.Player.Spawning"/>
        internal void OnSpawned(SpawnedEventArgs ev)
        {
            if (!ValidSpawnReasons.Contains(ev.Reason) || ev.Player.HasAnyCustomRole())
                return;

            float totalChance = 0f;
            List<CustomRole> eligibleRoles = new(8);

            foreach (CustomRole role in CustomRole.Registered)
            {
                if (role.Role == ev.Player.Role.Type && !role.IgnoreSpawnSystem && role.SpawnChance > 0 && (role.SpawnProperties is null || role.SpawnedPlayers < role.SpawnProperties.Limit) && (role.MinPlayers is 0 || Server.PlayerConnectedCount >= role.MinPlayers))
                {
                    eligibleRoles.Add(role);
                    totalChance += role.SpawnChance;
                }
            }

            if (eligibleRoles.Count == 0)
                return;

            float lotterySize = Mathf.Max(100f, totalChance);
            float randomRoll = (float)Loader.Loader.Random.NextDouble() * lotterySize;

            if (randomRoll >= totalChance)
                return;

            foreach (CustomRole candidateRole in eligibleRoles)
            {
                if (randomRoll >= candidateRole.SpawnChance)
                {
                    randomRoll -= candidateRole.SpawnChance;
                    continue;
                }

                candidateRole.SpawnedPlayers++;
                candidateRole.AddRole(ev.Player);
                break;
            }
        }
    }
}

namespace Exiled.CustomRoles
{
    using System.Collections.Generic;

    using Exiled.API.Features;
    using Exiled.CustomRoles.API.Features;
    using Exiled.CustomRoles.API.Features.Parsers;
    using Exiled.CustomRoles.Events;
    using Exiled.Loader;
    using Exiled.Loader.Features.Configs.CustomConverters;

    using YamlDotNet.Serialization;
    using YamlDotNet.Serialization.NamingConventions;
    using YamlDotNet.Serialization.NodeDeserializers;

    /// <summary>
    /// Handles all custom role API functions.
    /// </summary>
    public class CustomRoles : Plugin<Config>
    {
        private PlayerHandlers? playerHandlers;
        private KeypressActivator? keypressActivator;

        /// <summary>
        /// Initializes a new instance of the <see cref="CustomRoles"/> class.
        /// </summary>
        public CustomRoles()
        {
            Loader.Deserializer = new DeserializerBuilder()
                .WithTypeConverter(new VectorsConverter())
                .WithTypeConverter(new ColorConverter())
                .WithTypeConverter(new AttachmentIdentifiersConverter())
                .WithNamingConvention(UnderscoredNamingConvention.Instance)
                .WithNodeDeserializer(inner => new AbstractClassNodeTypeResolver(inner, new AggregateExpectationTypeResolver<CustomAbility>(UnderscoredNamingConvention.Instance)), s => s.InsteadOf<ObjectNodeDeserializer>())
                .IgnoreFields()
                .IgnoreUnmatchedProperties()
                .Build();
        }

        /// <summary>
        /// Gets a static reference to the plugin's instance.
        /// </summary>
        public static CustomRoles Instance { get; private set; } = null!;

        /// <summary>
        /// Gets a list of players to stop spawning ragdolls for.
        /// </summary>
        internal List<Player> StopRagdollPlayers { get; } = new();

        /// <inheritdoc/>
        public override void OnEnabled()
        {
            Instance = this;
            playerHandlers = new PlayerHandlers(this);

            if (Config.UseKeypressActivation)
                keypressActivator = new();

            Exiled.Events.Handlers.Player.Spawned += playerHandlers.OnSpawned;
            Exiled.Events.Handlers.Player.SpawningRagdoll += playerHandlers.OnSpawningRagdoll;

            Exiled.Events.Handlers.Server.WaitingForPlayers += playerHandlers.OnWaitingForPlayers;
            base.OnEnabled();
        }

        /// <inheritdoc/>
        public override void OnDisabled()
        {
            Exiled.Events.Handlers.Player.Spawned -= playerHandlers!.OnSpawned;
            Exiled.Events.Handlers.Player.SpawningRagdoll -= playerHandlers!.OnSpawningRagdoll;

            Exiled.Events.Handlers.Server.WaitingForPlayers -= playerHandlers!.OnWaitingForPlayers;

            keypressActivator = null;
            base.OnDisabled();
        }
    }
}

