namespace Exiled.CustomRoles.API
{
    using System;
    using System.Collections.Generic;
    using System.Collections.ObjectModel;
    using System.Linq;

    using Exiled.API.Features;
    using Exiled.CustomRoles.API.Features;
    using Exiled.CustomRoles.API.Features.Enums;

    using Utils.NonAllocLINQ;

    /// <summary>
    /// A collection of API methods.
    /// </summary>
    public static class Extensions
    {
        /// <summary>
        /// Gets a <see cref="ReadOnlyCollection{T}"/> of the player's current custom roles.
        /// </summary>
        /// <param name="player">The <see cref="Player"/> to check for roles.</param>
        /// <returns>A <see cref="ReadOnlyCollection{T}"/> of all current custom roles.</returns>
        public static ReadOnlyCollection<CustomRole> GetCustomRoles(this Player player)
        {
            List<CustomRole> roles = new();

            foreach (CustomRole customRole in CustomRole.Registered)
            {
                if (customRole.Check(player))
                    roles.Add(customRole);
            }

            return roles.AsReadOnly();
        }

        /// <summary>
        /// Checks whether the player has any custom role assigned.
        /// </summary>
        /// <param name="player">The <see cref="Player"/> to check.</param>
        /// <returns><c>true</c> if the player has at least one custom role; otherwise, <c>false</c>.</returns>
        public static bool HasAnyCustomRole(this Player player)
        {
            if (player == null)
                return false;

            foreach (CustomRole role in CustomRole.Registered)
            {
                if (role.Check(player))
                    return true;
            }

            return false;
        }

        /// <summary>
        /// Registers an <see cref="IEnumerable{T}"/> of <see cref="CustomRole"/>s.
        /// </summary>
        /// <param name="customRoles"><see cref="CustomRole"/>s to be registered.</param>
        public static void Register(this IEnumerable<CustomRole> customRoles)
        {
            if (customRoles is null)
                throw new ArgumentNullException(nameof(customRoles));

            foreach (CustomRole customRole in customRoles)
                customRole.TryRegister();
        }

        /// <summary>
        /// Registers a <see cref="CustomRole"/>.
        /// </summary>
        /// <param name="role"><see cref="CustomRole"/> to be registered.</param>
        public static void Register(this CustomRole role) => role.TryRegister();

        /// <summary>
        /// Registers a <see cref="CustomAbility"/>.
        /// </summary>
        /// <param name="ability">The <see cref="CustomAbility"/> to be registered.</param>
        public static void Register(this CustomAbility ability) => ability.TryRegister();

        /// <summary>
        /// Unregisters an <see cref="IEnumerable{T}"/> of <see cref="CustomRole"/>s.
        /// </summary>
        /// <param name="customRoles"><see cref="CustomRole"/>s to be unregistered.</param>
        public static void Unregister(this IEnumerable<CustomRole> customRoles)
        {
            if (customRoles is null)
                throw new ArgumentNullException(nameof(customRoles));

            foreach (CustomRole customRole in customRoles)
                customRole.TryUnregister();
        }

        /// <summary>
        /// Unregisters a <see cref="CustomRole"/>.
        /// </summary>
        /// <param name="role"><see cref="CustomRole"/> to be unregistered.</param>
        public static void Unregister(this CustomRole role) => role.TryUnregister();

        /// <summary>
        /// Unregisters a <see cref="CustomAbility"/>.
        /// </summary>
        /// <param name="ability">The <see cref="CustomAbility"/> to be unregistered.</param>
        public static void Unregister(this CustomAbility ability) => ability.TryUnregister();

        /// <summary>
        /// Gets all <see cref="ActiveAbility"/>s a specific <see cref="Player"/> is able to use.
        /// </summary>
        /// <param name="player">The <see cref="Player"/> to get abilities for.</param>
        /// <returns>A <see cref="IEnumerable{T}"/> of their active abilities, or <see langword="null"/> if none.</returns>
        public static IEnumerable<ActiveAbility>? GetActiveAbilities(this Player player) => !ActiveAbility.AllActiveAbilities.TryGetValue(player, out HashSet<ActiveAbility> abilities) ? null : abilities;

        /// <summary>
        /// Gets the <see cref="Player"/>'s selected ability.
        /// </summary>
        /// <param name="player">The <see cref="Player"/> to check.</param>
        /// <returns>The <see cref="ActiveAbility"/> the <see cref="Player"/> has selected, or <see langword="null"/>.</returns>
        public static ActiveAbility? GetSelectedAbility(this Player player) => !ActiveAbility.AllActiveAbilities.TryGetValue(player, out HashSet<ActiveAbility> abilities) ? null : abilities.FirstOrDefault(a => a.Check(player, CheckType.Selected));
    }
}

namespace Exiled.CustomItems.Commands
{
    using System;
    using System.Collections.Generic;
    using System.Linq;

    using CommandSystem;

    using Exiled.API.Features;
    using Exiled.CustomItems.API.Features;
    using Exiled.Permissions.Extensions;

    using RemoteAdmin;
    using UnityStandardAssets.Effects;
    using Utils;

    /// <summary>
    /// The command to give a player an item.
    /// </summary>
    internal sealed class Give : ICommand
    {
        private Give()
        {
        }

        /// <summary>
        /// Gets the <see cref="Give"/> instance.
        /// </summary>
        public static Give Instance { get; } = new();

        /// <inheritdoc/>
        public string Command { get; } = "give";

        /// <inheritdoc/>
        public string[] Aliases { get; } = { "g" };

        /// <inheritdoc/>
        public string Description { get; } = "Gives a custom item.";

        /// <inheritdoc/>
        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            if (!sender.CheckPermission("customitems.give"))
            {
                response = "Permission Denied, required: customitems.give";
                return false;
            }

            if (arguments.Count == 0)
            {
                response = "give <Custom item name/Custom item ID> [Nickname/PlayerID/UserID/all/*]";
                return false;
            }

            if (!CustomItem.TryGet(arguments.At(0), out CustomItem? item))
            {
                response = $"Custom item {arguments.At(0)} not found!";
                return false;
            }

            if (arguments.Count == 1)
            {
                if (sender is PlayerCommandSender playerCommandSender)
                {
                    Player player = Player.Get(playerCommandSender.SenderId);

                    if (!CheckEligible(player))
                    {
                        response = "You cannot receive custom items!";
                        return false;
                    }

                    item?.Give(player);
                    response = $"{item?.Name} given to {player.Nickname} ({player.UserId})";
                    return true;
                }

                response = "Failed to provide a valid player, please follow the syntax.";
                return false;
            }

            string identifier = string.Join(" ", arguments.Skip(1));

            switch (identifier)
            {
                case "*":
                case "all":
                    List<Player> eligiblePlayers = Player.List.Where(CheckEligible).ToList();
                    foreach (Player ply in eligiblePlayers)
                        item?.Give(ply);

                    response = $"Custom item {item?.Name} given to all players who can receive them ({eligiblePlayers.Count} players)";
                    return true;
                default:
                    break;
            }

            IEnumerable<Player> list = Player.GetProcessedData(arguments, 1);

            if (list.IsEmpty())
            {
                response = "Cannot find player! Try using the player ID!";
                return false;
            }

            foreach (Player player in list)
            {
                if (CheckEligible(player))
                {
                    item?.Give(player);
                }
            }

            response = $"{item?.Name} given to {list.Count()} players!";
            return true;
        }

        /// <summary>
        /// Checks if the player is eligible to receive custom items.
        /// </summary>
        private bool CheckEligible(Player player) => player.IsAlive && !player.IsCuffed && (player.Items.Count < 8);
    }
}

namespace Exiled.CustomItems.Commands
{
    using System;
    using System.Text;

    using CommandSystem;

    using Exiled.API.Features.Pools;
    using Exiled.API.Features.Spawn;
    using Exiled.CustomItems.API.Features;
    using Exiled.Permissions.Extensions;

    /// <summary>
    /// The command to view info about a specific item.
    /// </summary>
    internal sealed class Info : ICommand
    {
        private Info()
        {
        }

        /// <summary>
        /// Gets the <see cref="Info"/> instance.
        /// </summary>
        public static Info Instance { get; } = new();

        /// <inheritdoc/>
        public string Command { get; } = "info";

        /// <inheritdoc/>
        public string[] Aliases { get; } = { "i" };

        /// <inheritdoc/>
        public string Description { get; } = "Gets more information about the specified custom item.";

        /// <inheritdoc/>
        public bool Execute(ArraySegment<string> arguments, ICommandSender sender, out string response)
        {
            if (!sender.CheckPermission("customitems.info"))
            {
                response = "Permission Denied, required: customitems.info";
                return false;
            }

            if (arguments.Count < 1)
            {
                response = "info [Custom item name/Custom item ID]";
                return false;
            }

            if (!(uint.TryParse(arguments.At(0), out uint id) && CustomItem.TryGet(id, out CustomItem? item)) &&
                !CustomItem.TryGet(arguments.At(0), out item))
            {
                response = $"{arguments.At(0)} is not a valid custom item.";
                return false;
            }

            StringBuilder message = StringBuilderPool.Pool.Get().AppendLine();

            message.Append("<color=#E6AC00>-</color> <color=#00D639>").Append(item?.Name).Append("</color> <color=#05C4EB>(").Append(item?.Id).AppendLine(")</color>")
                .Append("- ").AppendLine(item?.Description)
                .AppendLine(item?.Type.ToString())
                .Append("- Spawn Limit: ").AppendLine(item?.SpawnProperties?.Limit.ToString()).AppendLine()
                .Append("[Spawn Locations (").Append(item?.SpawnProperties?.Count()).AppendLine(")]");

            foreach (DynamicSpawnPoint spawnPoint in item?.SpawnProperties?.DynamicSpawnPoints!)
                message.Append(spawnPoint.Name).Append(' ').Append(spawnPoint.Position).Append(" Chance: ").Append(spawnPoint.Chance).AppendLine("%");

            foreach (StaticSpawnPoint spawnPoint in item.SpawnProperties.StaticSpawnPoints)
                message.Append(spawnPoint.Name).Append(' ').Append(spawnPoint.Position).Append(" Chance: ").Append(spawnPoint.Chance).AppendLine("%");

            foreach (RoleSpawnPoint spawnPoint in item.SpawnProperties.RoleSpawnPoints)
                message.Append(spawnPoint.Name).Append(' ').Append(spawnPoint.Position).Append(" Chance: ").Append(spawnPoint.Chance).AppendLine("%");

            foreach (LockerSpawnPoint spawnPoint in item.SpawnProperties.LockerSpawnPoints)
                message.Append(spawnPoint.Name).Append(' ').Append(spawnPoint.Position).Append(" Chance: ").Append(spawnPoint.Chance).AppendLine("%");

            foreach (RoomSpawnPoint spawnPoint in item.SpawnProperties.RoomSpawnPoints)
                message.Append(spawnPoint.Name).Append(' ').Append(spawnPoint.Position).Append(" Chance: ").Append(spawnPoint.Chance).AppendLine("%");

            response = StringBuilderPool.Pool.ToStringReturn(message);
            return true;
        }
    }
}

